// Hit rate against cache size for all four policies (cached copies deleted on change).
// The model, shared by both cells: 10,000 keys with Zipf popularity (a few are asked
// for constantly), a database that answers in 15-40 ms and keeps changing, and a
// cache in front of it (cache-aside: look in the cache, on a miss read the database
// and put the answer in the cache).
function mulberry32(seed) {
  return () => {
    seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const KEYS = 10000;
const cdf = [];
{ let total = 0; for (let k = 1; k <= KEYS; k++) { total += 1 / k; cdf.push(total); } for (let k = 0; k < KEYS; k++) cdf[k] /= total; }
function zipfKey(r) { let lo = 0, hi = KEYS - 1; while (lo < hi) { const m = (lo + hi) >> 1; if (cdf[m] < r) lo = m + 1; else hi = m; } return lo; }

// Four eviction policies with the same interface: get(key) -> entry or undefined, set(key, entry).
function makeCache(policy, size, rand) {
  if (policy === 'LRU' || policy === 'FIFO') {
    const map = new Map();                         // a Map remembers insertion order
    return {
      get(k) { const e = map.get(k); if (e && policy === 'LRU') { map.delete(k); map.set(k, e); } return e; },
      set(k, e) { map.delete(k); if (map.size >= size) map.delete(map.keys().next().value); map.set(k, e); },
    };
  }
  if (policy === 'random') {
    const map = new Map(), keys = [];
    return {
      get(k) { return map.get(k)?.e; },
      set(k, e) {
        if (map.has(k)) { map.get(k).e = e; return; }
        if (keys.length >= size) {                 // evict a random key: swap it to the end, pop
          const i = Math.floor(rand() * keys.length), gone = keys[i];
          keys[i] = keys[keys.length - 1]; map.get(keys[i]).i = i; keys.pop(); map.delete(gone);
        }
        map.set(k, { e, i: keys.length }); keys.push(k);
      },
    };
  }
  // LFU in O(1): keys grouped by how often they were used; evict from the least-used group.
  const entries = new Map(), groups = new Map();
  let minFreq = 0;
  const touch = (k, item) => {
    const g = groups.get(item.f); g.delete(k);
    if (!g.size) { groups.delete(item.f); if (minFreq === item.f) minFreq++; }
    item.f++;
    if (!groups.has(item.f)) groups.set(item.f, new Set());
    groups.get(item.f).add(k);
  };
  return {
    get(k) { const item = entries.get(k); if (item) { touch(k, item); return item.e; } },
    set(k, e) {
      const item = entries.get(k);
      if (item) { item.e = e; touch(k, item); return; }
      if (entries.size >= size) {
        const g = groups.get(minFreq), gone = g.values().next().value;
        g.delete(gone); if (!g.size) groups.delete(minFreq); entries.delete(gone);
      }
      entries.set(k, { e, f: 1 });
      if (!groups.has(1)) groups.set(1, new Set());
      groups.get(1).add(k); minFreq = 1;
    },
  };
}

// Run the workload: 2,000 requests a second, and the database changes `updates` keys a second.
// invalidate = delete the cached copy whenever the database changes it (otherwise only the TTL helps).
function simulate({ policy, size, ttl, updates, invalidate, requests = 100000, seed = 40 }) {
  const rand = mulberry32(seed), cache = makeCache(policy, size, rand);
  const version = new Int32Array(KEYS), latency = new Float64Array(requests);
  let hits = 0, stale = 0, now = 0;
  for (let n = 0; n < requests; n++) {
    now += 0.5;                                    // ms
    if (rand() < updates / 2000) version[zipfKey(rand())]++;      // the database changes
    const key = zipfKey(rand());
    let e = cache.get(key);
    if (e && ttl > 0 && now - e.at > ttl * 1000) e = undefined;   // expired
    if (e && invalidate && e.version !== version[key]) e = undefined;   // deleted when the database changed
    if (e) {
      hits++;
      if (e.version !== version[key]) stale++;
      latency[n] = 0.2 + rand() * 0.3;            // a cache read: well under a millisecond
    } else {
      latency[n] = 0.5 + 15 + rand() * 25;        // a database read: 15-40 ms
      cache.set(key, { version: version[key], at: now });
    }
  }
  const hist = new Array(42).fill(0);
  for (const ms of latency) hist[Math.min(41, Math.floor(ms))]++;
  latency.sort();
  return { hist, hitRate: hits / requests, staleShare: stale / requests, p50: latency[requests >> 1],
           p99: latency[Math.floor(requests * 0.99)], mean: latency.reduce((a, b) => a + b, 0) / requests };
}

const updates = +(nb.get('kv_updates') ?? 20);
const sizes = [50, 100, 200, 500, 1000, 2000, 5000];
const rows = [];
console.log('cache size   ' + ['LRU', 'LFU', 'FIFO', 'random'].map(p => p.padStart(8)).join(''));
for (const size of sizes) {
  const line = [];
  for (const policy of ['LRU', 'LFU', 'FIFO', 'random']) {
    const r = simulate({ policy, size, ttl: 0, updates, invalidate: true });
    rows.push({ size, hitRate: r.hitRate, policy });
    line.push(((100 * r.hitRate).toFixed(1) + '%').padStart(8));
  }
  console.log(String(size).padStart(10) + '   ' + line.join(''));
}
const lru500 = simulate({ policy: 'LRU', size: 500, ttl: 0, updates, invalidate: true });
console.log('\nLRU, 500 entries: average request ' + lru500.mean.toFixed(1) + ' ms, against ' +
  simulate({ policy: 'LRU', size: 1, ttl: 0, updates, invalidate: true }).mean.toFixed(1) + ' ms with almost no cache');
return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 260,
  title: 'Hit rate against cache size, 10,000 keys with Zipf popularity',
  data: { values: rows },
  mark: { type: 'line', point: true },
  encoding: {
    x: { field: 'size', type: 'quantitative', scale: { type: 'log' }, title: 'cache size in entries (log scale)' },
    y: { field: 'hitRate', type: 'quantitative', axis: { format: '%' }, title: 'hit rate' },
    color: { field: 'policy', type: 'nominal', title: null },
  },
};
